// Each workflow intentionally performs visibility checks only. It documents the
// real local surface without submitting credentials, connecting a service, or
// triggering audio, OBS, printing, haptics, or a guest session.
function C(de, en, es, fr) {
  const make = ([title, body, expected]) => ({ title, body, expected, alt: `${title}: ${expected}` });
  return { de: make(de), en: make(en), es: make(es), fr: make(fr) };
}

function G(de, en, es, fr) {
  const make = ([title, summary, firstResult, requirements, safety, troubleshooting]) => ({
    title, summary, firstResult, requirements, safety, troubleshooting
  });
  return { de: make(de), en: make(en), es: make(es), fr: make(fr) };
}

